    func loadConversations() async throws  -> [ConversationRow]
    
    func markRecalled(convId: String, id: String, cliMsgId: String) async throws 
    
    /**
     * One message by server id or client id.
     */
    func message(convId: String, idOrClientId: String) async throws  -> MessageRow?
    
    /**
     * [`CoreStore::message`] decoded to a typed message in Rust (no JSON reaches Swift). `None` when the row is
     * missing or its JSON cannot be decoded (Swift's `decodeStoredMessage` returns nil for those).
     */
    func messageChat(convId: String, idOrClientId: String) async throws  -> StoredChat?
    
    /**
     * Messages of `conv_id`, oldest to newest; `before_ts_ms` fetches strictly older rows;
     * `limit` is clamped to 1...500.
     */
    func messages(convId: String, beforeTsMs: Int64?, limit: Int64) async throws  -> [MessageRow]
    
    /**
     * Window from `target_ts_ms` upward plus `context_before` earlier messages (Swift defaults
     * 25 / 3000).
     */
    func messagesAround(convId: String, targetTsMs: Int64, beforeOldestTsMs: Int64?, contextBefore: Int64, maxWindow: Int64) async throws  -> MessagesAroundRow
    
    /**
     * [`CoreStore::messages_around`] decoded to typed messages.
     */
    func messagesAroundChat(convId: String, targetTsMs: Int64, beforeOldestTsMs: Int64?, contextBefore: Int64, maxWindow: Int64) async throws  -> StoredChatAround
    
    /**
     * [`CoreStore::messages`] decoded to typed messages in Rust (no JSON reaches Swift).
     */
    func messagesChat(convId: String, beforeTsMs: Int64?, limit: Int64) async throws  -> [StoredChat]
    
    /**
     * The preference as a JSON bool, else `default_value`.
     */
    func preferenceBool(key: String, defaultValue: Bool) async throws  -> Bool
    
    /**
     * Raw JSON bytes of a preference (any type), or `None`.
     */
    func preferenceData(key: String) async throws  -> Data?
    
    func preferenceString(key: String) async throws  -> String?
    
    /**
     * The preference as `[String]` (empty when absent or malformed).
     */
    func preferenceStrings(key: String) async throws  -> [String]
    
    /**
     * Synchronous snapshot read of the newest `limit` messages (oldest first) through the read-only connection,
     * decoded to typed messages. `None` when there is no reader or the query failed. Takes well under a millisecond
     * for a screenful, so it is safe on the main thread (it never waits on the writer).
     */
    func readChatMessagesNow(convId: String, beforeTsMs: Int64?, limit: Int64)  -> [StoredChat]?
    
    /**
     * Saves typed messages: each is encoded to the canonical JSON row in Rust (`encodeChatMessage`; rows that cannot
     * be encoded are skipped). Flags as `save_messages_with`.
     */
    func saveChatMessages(items: [ChatMessageRecord], skipTwinChecks: Bool, preserveExistingReactions: Bool) async throws 
    
    func saveConversations(items: [ConversationRow]) async throws 
    
    func saveMessages(items: [MessageRow]) async throws 
    
    /**
     * Like `save_messages` with the Swift flags: `skip_twin_checks` (bulk fast path) and
     * `preserve_existing_reactions`.
     */
    func saveMessagesWith(items: [MessageRow], skipTwinChecks: Bool, preserveExistingReactions: Bool) async throws 
    
    /**
     * Case-insensitive search in one conversation, newest first (`limit` clamped to 1...500).
     */
    func searchMessages(convId: String, query: String, limit: Int64) async throws  -> [MessageRow]
    
    /**
     * [`CoreStore::search_messages`] decoded to typed messages.
     */
    func searchMessagesChat(convId: String, query: String, limit: Int64) async throws  -> [StoredChat]
    
    func setConversationPinned(id: String, pinned: Bool) async throws 
    
    func setConversationPreview(id: String, previewText: String, previewTsMs: Int64, previewFromMe: Bool, updatedAtMs: Int64) async throws 
    
    func setConversationUnread(id: String, unread: Int64) async throws 
    
    func setPreferenceBool(key: String, value: Bool) async throws 
    
    func setPreferenceData(key: String, data: Data) async throws 
    
    func setPreferenceString(key: String, value: String) async throws 
    
    func setPreferenceStrings(key: String, value: [String]) async throws 
    
    /**
     * Replaces `$.reactions` of a stored message with `reactions_json` (UTF-8 JSON array).
     */
    func updateMessageReactionsJson(convId: String, id: String, reactionsJson: Data) async throws 
    
    /**
     * Re-keys a local message to its server id; true when a row changed.
     */
    func upgradeMessageId(convId: String, oldId: String, newId: String, clientId: String) async throws  -> Bool
    
    func upsertConversation(item: ConversationRow) async throws 
    
}
