/**
 * Error thrown by every fallible export (`throws CoreError` in Swift). Variants carry a
 * human-readable `message` that never contains tokens or message bodies.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Store(message: String
    )
    case Parse(message: String
    )
    case Crypto(message: String
    )
    case Ws(message: String
    )
    case Internal(message: String
    )
    /**
     * The server answered with a non-zero `error_code` (Swift `ZaloSessionError`). `is_auth` is
     * true for 600 / -102: the session is dead, re-login.
     */
    case Session(code: Int64, message: String, isAuth: Bool
    )
    /**
     * Socket / DNS / TLS / timeout failure (the message never contains the request URL).
     */
    case Network(kind: NetworkKind, message: String
    )
    /**
     * Non-2xx HTTP answer.
     */
    case Http(status: UInt16
    )
    /**
     * No logged-in session (Swift `ZaloTransportError.notAuthenticated`).
     */
    case NotAuthenticated
    /**
     * QR login failed; `message` is a user-facing Vietnamese string from the engine.
     */
    case Qr(message: String
    )
    /**
     * The QR code expired before it was scanned / confirmed.
     */
    case QrTimeout
    /**
     * The operation was cancelled.
     */
    case Cancelled

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Store(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Parse(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Crypto(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Ws(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Session(
            code: try FfiConverterInt64.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf), 
            isAuth: try FfiConverterBool.read(from: &buf)
            )
        case 7: return .Network(
            kind: try FfiConverterTypeNetworkKind.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Http(
            status: try FfiConverterUInt16.read(from: &buf)
            )
        case 9: return .NotAuthenticated
        case 10: return .Qr(
            message: try FfiConverterString.read(from: &buf)
            )
        case 11: return .QrTimeout
        case 12: return .Cancelled

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Store(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Parse(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Crypto(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Ws(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Internal(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Session(code,message,isAuth):
            writeInt(&buf, Int32(6))
            FfiConverterInt64.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(isAuth, into: &buf)
            
        
        case let .Network(kind,message):
            writeInt(&buf, Int32(7))
            FfiConverterTypeNetworkKind.write(kind, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Http(status):
            writeInt(&buf, Int32(8))
            FfiConverterUInt16.write(status, into: &buf)
            
        
        case .NotAuthenticated:
            writeInt(&buf, Int32(9))
        
        
        case let .Qr(message):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(message, into: &buf)
            
        
        case .QrTimeout:
            writeInt(&buf, Int32(11))
        
        
        case .Cancelled:
            writeInt(&buf, Int32(12))
        
        }
    }
}


